const allInputs = $input.all();

// ChatGPT returns array of items with "output" field
let articles = [];

for (const input of allInputs) {
  const json = input.json;

  // Check if this is ChatGPT format with "output" field
  if (json.output) {
    let responseText = json.output;

    // Clean markdown
    responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // Skip empty responses
    if (responseText === '[]' || !responseText) continue;

    try {
      const parsed = JSON.parse(responseText);
      if (Array.isArray(parsed) && parsed.length > 0) {
        articles = articles.concat(parsed);
      }
    } catch (e) {
      console.error('Parse error:', e.message);
    }
  }
}

console.log('Total articles found:', articles.length);

// Date filtering function
function isArticleFresh(dateStr) {
  if (!dateStr) return false;

  const lower = dateStr.toLowerCase();

  // Accept 2026 dates
  if (dateStr.includes('2026')) {
    // Reject anything before October 2025
    if (dateStr.includes('2025')) {
      const months = ['october', 'november', 'december'];
      return months.some(m => lower.includes(m));
    }
    return true;
  }

  // Accept very recent dates
  if (lower.includes('hour') || lower.includes('today') || lower.includes('yesterday')) {
    return true;
  }

  // Accept "this week"
  if (lower.includes('this week')) {
    return true;
  }

  // Accept recent days (1-7 days ago)
  if (lower.includes('day')) {
    const match = dateStr.match(/(\d+)\s*day/i);
    if (match && parseInt(match[1]) <= 7) {
      return true;
    }
  }

  // Reject 2023, 2024, early 2025
  if (dateStr.includes('2023') || dateStr.includes('2024')) {
    return false;
  }

  if (dateStr.includes('2025')) {
    // Only accept Oct, Nov, Dec 2025
    const months = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september'];
    if (months.some(m => lower.includes(m))) {
      return false;
    }
  }

  return false;
}

// Filter articles
const freshArticles = articles.filter(a => {
  const isFresh = isArticleFresh(a.published_date);
  if (!isFresh) {
    console.log('Filtered out OLD:', a.headline, '- Date:', a.published_date);
  }
  return isFresh;
});

console.log('After date filter:', freshArticles.length, 'articles');

if (freshArticles.length === 0) {
  return [];
}

// Get query data from first input
