};

return [{ json: enrichedStory }];

// Select best Unsplash image
const response = $input.first().json;
const storyData = $input.first().json;

let imageUrl = null;
let imageData = null;

try {
  const results = response.results || [];
  if (results.length > 0) {
    // Get first result
    const image = results[0];
    imageUrl = image.urls.regular; // High quality but not full size

    // Download image
    const imageResponse = await fetch(imageUrl);
    const imageBlob = await imageResponse.blob();
    const arrayBuffer = await imageBlob.arrayBuffer();
    imageData = Buffer.from(arrayBuffer);
  }
} catch (e) {
  console.error('Failed to get Unsplash image:', e.message);
}

if (!imageUrl) {
  console.error('No Unsplash images found');
  return [];
}

return [{
  json: {
    ...storyData,
    image_url: imageUrl,
    image_source: 'unsplash',
    image_data: imageData
  }
}];

// Extract and validate post
const storyData = $input.first().json;
const postResponse = $input.all()[1]?.json || $input.first().json;

let postContent = postResponse.response || postResponse.text || '';
postContent = postContent.replace(/```\n?/g, '').trim();

// Quality checks for institutional voice
const wordCount = postContent.split(/\s+/).length;
const hasEmoji = /[\u{1F300}-\u{1F9FF}]/u.test(postContent);
const emojiCount = (postContent.match(/[\u{1F300}-\u{1F9FF}]/gu) || []).length;
const hasNumbers = /\d/.test(postContent);
const hasBullets = /[•\-]/.test(postContent);
const hasSource = postContent.toLowerCase().includes('source:');
const hasURL = /https?:\/\//.test(postContent);

// Institutional voice checks
const hasExperience = /amazon|advisory|clients?|boards?|institutions?/i.test(postContent);
const hasInstitutional = /family office|uhnwi|sovereign wealth|institutional|fiduciary|compliance|governance/i.test(postContent);
const avoidHype = !/wild|insane|crazy|game-?changer|revolutionary/i.test(postContent);
const hasSpecifics = (postContent.match(/\$\d+[MBK]|\d+%|\d+ (companies|institutions|funds)/gi) || []).length >= 2;

// Calculate quality score (0-10)
let qualityScore = 0;
qualityScore += (wordCount >= 180 && wordCount <= 320) ? 2 : 0; // Right length
qualityScore += (emojiCount >= 1 && emojiCount <= 3) ? 1 : 0;  // Professional emoji use
qualityScore += hasNumbers ? 1 : 0;                             // Has data
qualityScore += hasBullets ? 1 : 0;                             // Has structure
qualityScore += (hasSource && hasURL) ? 1 : 0;                  // Proper attribution
qualityScore += hasExperience ? 1 : 0;                          // References expertise
qualityScore += hasInstitutional ? 1 : 0;                       // Institutional framing
qualityScore += avoidHype ? 1 : 0;                              // No hype language
qualityScore += hasSpecifics ? 1 : 0;                           // Specific data points

// Status determination
let status = 'needs_review';
if (qualityScore >= 8) {
  status = 'approved';
} else if (qualityScore >= 6) {
  status = 'needs_minor_edits';
}

const finalOutput = {
  // Post content
  post_content: postContent,

  // Story metadata
  headline: storyData.headline,
  source: storyData.source,
  source_url: storyData.url,
  published_date: storyData.published_date,

  // Image data
  image_url: storyData.image_url,
  image_source: storyData.image_source,
  image_data: storyData.image_data,
  has_video: storyData.has_video || false,

  // Scores
  selection_score: storyData.selection_score || 0,
  institutional_relevance: storyData.institutional_relevance || 0,
  quality_score: qualityScore,

  // Analysis
  key_stats: storyData.key_stats || [],
  institutional_implications: storyData.institutional_implications || '',
  damu_angle_ideas: storyData.damu_angle_ideas || [],
  executives_quoted: storyData.executives_quoted || [],

  // Metadata
  word_count: wordCount,
  emoji_count: emojiCount,
  has_numbers: hasNumbers,
  has_bullets: hasBullets,
  has_institutional_framing: hasInstitutional,
  has_experience_reference: hasExperience,
  avoids_hype: avoidHype,
  has_specific_data: hasSpecifics,
  status: status,
  content_type: storyData.content_type,
  target_segment: storyData.target_segment,
  created_at: new Date().toISOString(),
  run_id: storyData.run_id,

  // Validation
  is_approved: status === 'approved',
  needs_review: status === 'needs_review'
};

return [{ json: finalOutput }];

